import ast, inspect, more_itertools.more as m, more_itertools.recipes as r
for mod,f in ((m,'more_itertools/more.pyi'),(r,'more_itertools/recipes.pyi')):
  t=ast.parse(open(f).read())
  stubs={}
  for n in t.body:
    if isinstance(n,(ast.FunctionDef)):
      a=n.args; stubs.setdefault(n.name,[]).append(([x.arg for x in a.posonlyargs+a.args],[x.arg for x in a.kwonlyargs]))
  for name in mod.__all__:
    obj=getattr(mod,name)
    if not inspect.isfunction(obj) or name not in stubs: continue
    sig=inspect.signature(obj)
    pos=[p.name for p in sig.parameters.values() if p.kind in (p.POSITIONAL_ONLY,p.POSITIONAL_OR_KEYWORD)]
    kw=[p.name for p in sig.parameters.values() if p.kind==p.KEYWORD_ONLY]
    if not any(s==(pos,kw) for s in stubs[name]):
      # allow overload subsets
      if not any(set(s[0])<=set(pos) and set(s[1])<=set(kw) for s in stubs[name]) or True:
        print(name, 'impl',pos,kw,'stub',stubs[name][:2])
"

