import sys, itertools, random, warnings, signal
warnings.simplefilter('ignore')
sys.path.insert(0, sys.argv[1]); sys.path.insert(0, sys.argv[2])
import more_itertools as N, ref_mi as R
class TO(Exception): pass
def h(*a): raise TO
signal.signal(signal.SIGALRM, h)
skip={'random_product','random_permutation','random_combination','random_combination_with_replacement','sample','interleave_randomly','random_derangement','repeatfunc','iterate','tabulate','loops','repeat_each','ncycles','repeat_last','cycle'}
names=sorted(set(R.more.__all__+R.recipes.__all__)&set(N.more.__all__+N.recipes.__all__)-skip)
def norm(r):
    if isinstance(r,(str,int,float,bool,type(None))): return repr(r)
    if isinstance(r,(list,tuple)): return '['+','.join(norm(x) for x in r)+']'
    if hasattr(r,'__iter__') and not isinstance(r,dict): return norm(list(itertools.islice(r,60)))
    return repr(r)
random.seed(11); slow={}; bad={}
for t in range(150):
    inp=[random.randint(0,5) for _ in range(random.randint(0,12))]
    ex=tuple(random.choice([random.randint(1,4),[random.randint(0,5) for _ in range(random.randint(0,6))]]) for _ in range(random.randint(0,2)))
    for name in names:
        if name in slow: continue
        res=[]
        for M,tag in ((N,'new'),(R,'ref')):
            signal.setitimer(signal.ITIMER_REAL,0.5)
            try: res.append(norm(getattr(M,name)(iter(inp),*ex)))
            except TO: res.append('TIMEOUT'); slow[name]=(tag,inp,ex)
            except Exception as e: res.append('E')
            finally: signal.setitimer(signal.ITIMER_REAL,0)
        a,b=res
        if a!=b and 'object at' not in a+b and 'E' not in (a,b) and name not in bad: bad[name]=(inp,ex,a[:120],b[:120])
print('SLOW',slow); 
for k,v in bad.items(): print(k,v)
